update public.learning_paths
set
  title = 'Public Health Ethics and Law',
  goal = 'Public Health Ethics and Law',
  summary = 'This course provides a comprehensive exploration of the legal and ethical frameworks that govern public health practice. Students will analyze the balance between individual liberties and the collective good, examining issues such as emergency powers, data privacy, health equity, and global health governance through contemporary case studies and policy analysis.',
  data = $pheljson${"slug": "public-health-ethics-and-law", "title": "Public Health Ethics and Law", "description": "This course provides a comprehensive exploration of the legal and ethical frameworks that govern public health practice. Students will analyze the balance between individual liberties and the collective good, examining issues such as emergency powers, data privacy, health equity, and global health governance through contemporary case studies and policy analysis.", "topics": [{"id": "bb1dcf24-5b5c-4d66-91cd-e9d50be44944", "type": "topic", "title": "Foundations of Public Health Ethics and Law", "description": "Introduce the relationship between population health goals, legal authority, ethical justification, and democratic accountability.", "children": [{"id": "3a716074-08bd-41b1-9993-7552eaff71a4", "type": "subtopic", "title": "Public health mission and authority", "description": "Students learn why public health uses collective action and when law becomes a tool for prevention.", "children": [{"id": "220b4cab-5b4c-491f-8f87-bf200fd32580", "type": "concept", "title": "Population health, prevention, health promotion, and social determinants"}, {"id": "f3daebc1-39a2-4bd6-9302-931adbe4c799", "type": "concept", "title": "Government duties and police powers"}, {"id": "cd478f1e-ee71-43eb-92b9-1b7ada048fd4", "type": "concept", "title": "Public health agencies, boards, and delegated authority"}]}, {"id": "80f61cb9-0ec4-4434-b03e-47f16d95279b", "type": "subtopic", "title": "Ethics and law relationship", "description": "The point is to distinguish what is legal, what is ethical, and what is legitimate.", "children": [{"id": "eae9a5f6-85ef-4e8b-ab80-44667503d7f9", "type": "concept", "title": "Legal permissibility versus ethical justification"}, {"id": "3aa89e48-77a8-42dc-88ac-92f47c34fbe5", "type": "concept", "title": "Rights, duties, powers, and constraints"}, {"id": "7d1c165c-4a4f-4391-bd85-c90112596470", "type": "concept", "title": "Accountability, transparency, and public reason-giving"}]}, {"id": "3988eb2c-f408-4372-b2b2-668172c5069d", "type": "subtopic", "title": "Case-based reasoning", "description": "Learners practice applying principles to messy real-world situations.", "children": [{"id": "6f430d20-a32c-4329-bf1f-3387c518ddec", "type": "concept", "title": "Facts, stakeholders, values, law, evidence, and uncertainty"}, {"id": "069f572f-344f-4071-9171-bd8875206b31", "type": "concept", "title": "Tradeoff analysis"}, {"id": "7d80df2f-911d-49db-a9f1-bac45cb37a0f", "type": "concept", "title": "Recommendations and justification"}]}]}, {"id": "9ed07dcf-78d1-4a34-aa15-ee6a7dff78d8", "type": "topic", "title": "Ethical Frameworks for Public Health Decision-Making", "description": "Use structured ethical reasoning to evaluate interventions, tradeoffs, and policy choices.", "children": [{"id": "5d45a3b3-c95a-4a3f-a268-c433b3d1cf5d", "type": "subtopic", "title": "Core ethical principles", "description": "Students build vocabulary for evaluating public health actions.", "children": [{"id": "b5223390-1eba-49b1-bf57-ca2bfc50a38c", "type": "concept", "title": "Beneficence, nonmaleficence, autonomy, justice, reciprocity, solidarity, and stewardship"}, {"id": "eb8adecf-548c-4092-82ca-7064c590ec52", "type": "concept", "title": "Population benefit and individual burden"}, {"id": "14c1102a-5d09-4b9e-8195-605b6045bd4d", "type": "concept", "title": "Least restrictive means"}]}, {"id": "a2405f73-3f41-413d-9614-226e2707c641", "type": "subtopic", "title": "Public health ethics frameworks", "description": "This subtopic teaches step-by-step reasoning for policy and practice.", "children": [{"id": "ebcaa6a5-e99c-4a1d-97c5-665bd3696a79", "type": "concept", "title": "Necessity, effectiveness, proportionality, fairness, and transparency"}, {"id": "35000acd-5b44-49ea-9c5b-d3bd98050af9", "type": "concept", "title": "Evidence, alternatives, and implementation feasibility"}, {"id": "78a6e2e8-03f7-431b-9a16-1031833cfe7b", "type": "concept", "title": "Procedural justice and accountability"}]}, {"id": "2ebdbc63-d5da-45af-bb2a-8bab6280ba8b", "type": "subtopic", "title": "Ethical uncertainty", "description": "Learners make defensible decisions even when evidence is incomplete.", "children": [{"id": "0ffb4ac7-5533-4eba-9f07-dd25085f6c52", "type": "concept", "title": "Precaution, uncertainty, contested values, and risk communication"}, {"id": "8072b669-0bf8-47b2-8250-cd655959f5fd", "type": "concept", "title": "Moral distress and disagreement"}, {"id": "f98ea5ec-730b-4d3f-976d-1f026b39677e", "type": "concept", "title": "Documentation of rationale"}]}]}, {"id": "b124784d-f1e4-4a86-a3a2-a55d6a646dd8", "type": "topic", "title": "Individual Rights, Liberty, and the Public Good", "description": "Examine when public health may limit individual liberty and what safeguards make restrictions legitimate.", "children": [{"id": "c5612e94-f50a-47f4-9d3c-7b3275a57a56", "type": "subtopic", "title": "Rights in public health", "description": "Students examine how liberty, privacy, bodily integrity, speech, religion, and equality arise in public health policy.", "children": [{"id": "be6d3caa-2a18-4cb8-8ff9-f0134e451806", "type": "concept", "title": "Constitutional rights and statutory protections"}, {"id": "797e906f-000e-4567-8a8b-506bf2ec8203", "type": "concept", "title": "Due process and equal protection concepts"}, {"id": "f84b2ed1-5baa-4d7d-b8dc-98382283b3d7", "type": "concept", "title": "Reasonable limits and public justification"}]}, {"id": "956f9838-f754-41d6-a8fa-1311d316d682", "type": "subtopic", "title": "Public good and collective risk", "description": "The gist is to understand why individual choices can create population-level consequences.", "children": [{"id": "cd64109a-957a-42ba-9ede-db7b6ea8ddcc", "type": "concept", "title": "Externalities, herd protection, environmental exposure, and communicable disease"}, {"id": "e8563912-9dcd-4c17-b2fb-63f73f2fe7b1", "type": "concept", "title": "Free rider problems"}, {"id": "11568007-b28c-4a00-9179-9332934fb826", "type": "concept", "title": "Community protection and vulnerable populations"}]}, {"id": "fdb64164-5d49-49c5-8867-9712a2e357b5", "type": "subtopic", "title": "Balancing tests and safeguards", "description": "Learners evaluate restrictions through necessity and fairness.", "children": [{"id": "756a9bfe-ad3c-4951-8440-7ea610d79461", "type": "concept", "title": "Least restrictive alternative"}, {"id": "8cb888a1-6cc8-4267-9949-6e57aa43c72a", "type": "concept", "title": "Narrow tailoring and time limits"}, {"id": "42fa807c-945f-4083-b2b1-54cb769de701", "type": "concept", "title": "Appeal, review, notice, and compensation where appropriate"}]}]}, {"id": "4b4d15b9-152f-46ac-884d-1453e3bf826e", "type": "topic", "title": "Health Equity, Justice, Structural Determinants, and Anti-Discrimination", "description": "Center equity and justice as legal and ethical obligations in public health practice.", "children": [{"id": "77983f92-902b-4161-882c-f30d1adb7357", "type": "subtopic", "title": "Justice and equity frameworks", "description": "Students learn to assess who benefits, who bears burdens, and who has voice.", "children": [{"id": "cab54e2b-fef8-43c0-9790-4e4645bb000c", "type": "concept", "title": "Distributive, procedural, corrective, and recognitional justice"}, {"id": "95ab4a0c-2e66-4296-a300-7037b8f65a5c", "type": "concept", "title": "Health disparities and inequities"}, {"id": "0d9fc3aa-37e8-4416-b406-dfe975556d58", "type": "concept", "title": "Priority-setting and resource allocation"}]}, {"id": "d22122bd-ab27-44d4-b8aa-a139807cff61", "type": "subtopic", "title": "Structural determinants and law", "description": "This subtopic shows how law can create or reduce health inequity.", "children": [{"id": "c9b2db57-264b-4919-8397-fcdce076fc63", "type": "concept", "title": "Housing, labor, education, environment, policing, immigration, and food systems"}, {"id": "3febd75d-ee3b-4144-b9fd-8c9dd40b4f97", "type": "concept", "title": "Structural racism and discrimination"}, {"id": "647a2c72-1ae8-4c14-a2fb-4185f9ff717b", "type": "concept", "title": "Health in All Policies"}]}, {"id": "101cf6d8-4bed-4619-b3c4-645e8d716ddb", "type": "subtopic", "title": "Equity impact assessment", "description": "Learners apply equity tools to policy decisions.", "children": [{"id": "2eb20a40-8439-486c-bad5-5798a175f0e4", "type": "concept", "title": "Disaggregated data"}, {"id": "5e41ec8b-8fb0-4bf4-a2d5-c112dcd837e7", "type": "concept", "title": "Community engagement"}, {"id": "c6f9ce8f-5c75-4732-93d7-b95c9068cfaf", "type": "concept", "title": "Unintended consequences and mitigation"}]}]}, {"id": "0866649f-cbcf-48f7-a5e6-6c6e78527fc4", "type": "topic", "title": "Public Health Law Foundations, Authority, and Federalism", "description": "Understand legal sources of public health power across federal, state, local, tribal, and territorial systems.", "children": [{"id": "98bce995-84d5-4cb0-b97a-5eff60621616", "type": "subtopic", "title": "Sources of public health law", "description": "Students learn where public health authority comes from.", "children": [{"id": "0d31482e-a2f0-44da-ad61-3def6d9dbc20", "type": "concept", "title": "Constitutions, statutes, regulations, ordinances, common law, and agency guidance"}, {"id": "58a449d5-dc8f-4f6c-82c6-38f8a22cadab", "type": "concept", "title": "Federal, state, local, tribal, and territorial authority"}, {"id": "af4daac1-f7b4-4b53-b7db-98b64a85a7ea", "type": "concept", "title": "Administrative law basics"}]}, {"id": "f379ff58-1c53-4782-95d8-fede567abe4b", "type": "subtopic", "title": "Federalism and jurisdiction", "description": "The point is to understand why public health powers vary across places.", "children": [{"id": "d9c2b91f-aae4-4466-ac4d-672fa45fe7a7", "type": "concept", "title": "State police power"}, {"id": "3c863d00-b0a4-4cf3-b093-07a81c8c8531", "type": "concept", "title": "Federal spending, commerce, and emergency powers"}, {"id": "cef39b5f-a33a-475c-b19d-1206d5ec7b8c", "type": "concept", "title": "Preemption, home rule, and local authority"}]}, {"id": "4b03b3c8-5e31-4a99-8b82-b9a04bbf79ce", "type": "subtopic", "title": "Legal limits and accountability", "description": "Learners identify checks on government action.", "children": [{"id": "5b189219-213b-47d9-b83f-15993c2b8c05", "type": "concept", "title": "Due process, equal protection, separation of powers, judicial review, and statutory limits"}, {"id": "7e35ef5c-7bdf-4d3e-89de-d7684ab46f14", "type": "concept", "title": "Notice-and-comment and public participation"}, {"id": "d910e832-2c99-43e9-b3ee-3c87667edd86", "type": "concept", "title": "Liability and immunity"}]}]}, {"id": "81869202-4b9d-4aa8-aece-d44f64e19fa4", "type": "topic", "title": "Informed Consent, Autonomy, Research Ethics, and Community Engagement", "description": "Clarify when consent is required, when population-level action differs, and how communities should be engaged.", "children": [{"id": "bd36dff4-e43c-4bed-9d5f-465eb9d08f15", "type": "subtopic", "title": "Informed consent in public health", "description": "Students distinguish clinical consent, research consent, and population-level interventions.", "children": [{"id": "7f0cea90-6a8e-4bbf-9eb1-41e7561a7ac3", "type": "concept", "title": "Disclosure, understanding, voluntariness, capacity, and authorization"}, {"id": "aece6e01-502d-4df3-b9f6-0e6717c2badf", "type": "concept", "title": "Screening, testing, treatment, and vaccination contexts"}, {"id": "9050ffd4-9a16-408d-9cb4-272b95b021ef", "type": "concept", "title": "Limits of consent in public health powers"}]}, {"id": "1541b9e4-47e8-4542-a241-b2c89ce705c2", "type": "subtopic", "title": "Research ethics", "description": "This subtopic connects public health practice to human-subjects protections.", "children": [{"id": "90e04081-b0b1-4814-a036-becbb7539eae", "type": "concept", "title": "Belmont principles, IRB review, community-based participatory research, and vulnerable populations"}, {"id": "87122b97-b85e-45da-bfa5-33777a689edf", "type": "concept", "title": "Public health practice versus research"}, {"id": "bb7adb2a-ae44-48f8-931b-e95e77c7d125", "type": "concept", "title": "Data use and secondary analysis"}]}, {"id": "4761dfbf-3ba0-499e-9c38-2192dca8b249", "type": "subtopic", "title": "Community engagement", "description": "Learners see engagement as an ethical requirement, not a public relations add-on.", "children": [{"id": "7304e5b6-3757-4720-8cd8-7666fea2d6c7", "type": "concept", "title": "Affected communities and trust"}, {"id": "d42fe7bd-08d2-45ee-9a40-093f40f07f95", "type": "concept", "title": "Shared decision-making"}, {"id": "6def942b-a9da-4e84-bb80-08d7fb12c62f", "type": "concept", "title": "Cultural humility and language access"}]}]}, {"id": "ec6797f5-5e84-449d-9ae4-dfedccaf6e06", "type": "topic", "title": "Surveillance, Data Governance, Privacy, HIPAA, and Confidentiality", "description": "Balance public health data needs with privacy, trust, security, and responsible data sharing.", "children": [{"id": "cf9f6917-5cc1-4608-814b-b6366f130cb5", "type": "subtopic", "title": "Public health surveillance authority", "description": "Students learn why surveillance is essential and ethically sensitive.", "children": [{"id": "0f97f8d8-6815-471f-be0e-db38e62b6178", "type": "concept", "title": "Reportable diseases, syndromic surveillance, registries, and contact tracing"}, {"id": "8690e802-4003-492e-8db6-44f5a87b1495", "type": "concept", "title": "Data collection authority"}, {"id": "d8ed76b9-b4b3-45ac-b52a-aab25c5e7431", "type": "concept", "title": "Minimum necessary and purpose limitation"}]}, {"id": "1e2c36ec-b580-4121-a495-b4e65bd11c53", "type": "subtopic", "title": "Privacy and HIPAA", "description": "The gist is to understand when health information may be used or disclosed for public health.", "children": [{"id": "3fa30944-c44e-47a9-9988-f4a8fe2a14bf", "type": "concept", "title": "Covered entities, public health exceptions, authorization, and de-identification"}, {"id": "6833eb61-6306-4628-99a0-85e26acc5a9d", "type": "concept", "title": "Confidentiality, security safeguards, and breach notification"}, {"id": "715ecf7b-5de3-4f98-be9c-8a3eb028100a", "type": "concept", "title": "State privacy laws and stricter protections"}]}, {"id": "df139591-366f-4e7a-ab1d-c1ad55c26e1e", "type": "subtopic", "title": "Data governance and trust", "description": "Learners build data practices that communities can trust.", "children": [{"id": "5d0814c5-fbb7-4f1e-a0bd-72f0c44dffb7", "type": "concept", "title": "Data sharing agreements, governance boards, access controls, retention, and transparency"}, {"id": "8751dd5d-cea4-41aa-9d81-7ac13bd2f02d", "type": "concept", "title": "Equity and bias in data systems"}, {"id": "a62330c7-46c0-4bab-96c1-273c69954c2f", "type": "concept", "title": "Public communication about data use"}]}]}, {"id": "8fc2a7e8-6cec-482f-8736-4fcdc6a4d0ef", "type": "topic", "title": "Communicable Disease Control, Quarantine, Isolation, and Due Process", "description": "Analyze coercive communicable-disease powers through necessity, proportionality, science, and procedural fairness.", "children": [{"id": "58f62e1f-15da-4a6b-9746-bd7835ff9d5c", "type": "subtopic", "title": "Disease-control powers", "description": "Students examine legal tools used to control communicable disease.", "children": [{"id": "5119c9e6-f7f5-4c4d-a16a-a4703a29d839", "type": "concept", "title": "Testing, reporting, contact tracing, treatment, quarantine, isolation, closure orders, and travel restrictions"}, {"id": "da0d5d12-e63e-46c7-8097-7ac1dee5f524", "type": "concept", "title": "Scientific evidence and necessity"}, {"id": "e5933298-d7a2-4519-9629-73a80801f5cb", "type": "concept", "title": "Local and state implementation"}]}, {"id": "def0d895-ff2c-435e-a271-5ecf07006e14", "type": "subtopic", "title": "Due process and safeguards", "description": "This subtopic focuses on fairness when liberty is restricted.", "children": [{"id": "b0bd4609-e8c1-4566-954c-c3939041bcd2", "type": "concept", "title": "Notice, hearing, counsel, review, time limits, and conditions of confinement"}, {"id": "e8c5a70c-007d-4941-80bc-ff126eb9d0c9", "type": "concept", "title": "Least restrictive means"}, {"id": "24b98452-599b-4d35-8885-d3482a851bac", "type": "concept", "title": "Support services and reciprocity"}]}, {"id": "ce3ad4c2-1210-424b-a2c6-f5f0b0c582c4", "type": "subtopic", "title": "Ethics of coercive measures", "description": "Learners assess when coercion may be justified and when it can backfire.", "children": [{"id": "f9f48ac6-7880-4c6e-81a4-0ae4e017c8cc", "type": "concept", "title": "Trust, stigma, discrimination, compliance, and enforcement"}, {"id": "f93f4fba-b1cc-4e20-8347-6a52deead7c0", "type": "concept", "title": "Voluntary measures first"}, {"id": "e10e3059-264f-4bc5-82c3-00ee54cc46f8", "type": "concept", "title": "Equitable support for affected persons"}]}]}, {"id": "144380cf-54cf-4c93-b23c-c8c3e5d4cbe6", "type": "topic", "title": "Vaccination Law, Mandates, Exemptions, and Public Trust", "description": "Study legal and ethical issues in vaccine policy, mandates, exemptions, communication, and equity.", "children": [{"id": "c86df6c1-103f-4359-bb4e-a302117a0693", "type": "subtopic", "title": "Vaccination authority", "description": "Students study how vaccine requirements are created and challenged.", "children": [{"id": "081a94a1-9ce5-405c-af77-c50ce4d4237c", "type": "concept", "title": "School, healthcare worker, employer, travel, and emergency mandates"}, {"id": "6197458f-bd3a-4238-a542-4f47ceeecdf2", "type": "concept", "title": "State law variation"}, {"id": "6ef7f5e4-18b4-45c3-80bb-069ee4bc93d6", "type": "concept", "title": "Medical, religious, and philosophical exemptions"}]}, {"id": "821a648a-8bda-4641-a958-cf8925a20194", "type": "subtopic", "title": "Ethics of mandates", "description": "The point is to balance autonomy, herd protection, equity, and public trust.", "children": [{"id": "524dc50e-6899-494c-b38e-0185228a4619", "type": "concept", "title": "Risk-benefit analysis"}, {"id": "ddccd810-fda0-45c8-9766-e90ba5aca12c", "type": "concept", "title": "Least restrictive alternatives"}, {"id": "03179dd3-1d32-4ebf-962f-83d5b013af9f", "type": "concept", "title": "Access barriers and distributional fairness"}]}, {"id": "f3a4ee9f-f141-44a0-b4bd-31d5ae36b28e", "type": "subtopic", "title": "Vaccine communication", "description": "Learners develop legally accurate and ethically respectful communication.", "children": [{"id": "2628ec95-91b0-49a8-9189-df9dc93749bf", "type": "concept", "title": "Misinformation, hesitancy, transparency, and uncertainty"}, {"id": "12a04c1a-b95d-43a5-837a-10eac4054461", "type": "concept", "title": "Community messengers"}, {"id": "987bff1e-e08f-4785-a428-5c9d8e0906e5", "type": "concept", "title": "Adverse event reporting and trust repair"}]}]}, {"id": "30cbb2ca-f4b8-41d8-bad2-a8bfc95c6ba3", "type": "topic", "title": "Emergency Powers, Crisis Standards, and Public Health Preparedness", "description": "Evaluate legal emergency authority and ethical decision-making during outbreaks, disasters, and scarcity.", "children": [{"id": "421ac4cf-be32-4dc6-a063-761b59260dc8", "type": "subtopic", "title": "Emergency declarations and powers", "description": "Students learn what changes when an emergency is declared.", "children": [{"id": "ad593a31-5126-4f18-b6c5-9ef35b4d58dd", "type": "concept", "title": "Emergency declarations, executive orders, agency powers, procurement, liability, and mutual aid"}, {"id": "253c8348-7cfa-47b8-bcb9-14ae43741fbd", "type": "concept", "title": "Time limits and legislative oversight"}, {"id": "c879523d-c8bd-49cd-88e7-fb1a871dc3d5", "type": "concept", "title": "Federal-state coordination"}]}, {"id": "985d984a-d88d-4b9f-b1cd-b70c2322e078", "type": "subtopic", "title": "Crisis standards of care", "description": "This subtopic explores ethical allocation when needs exceed resources.", "children": [{"id": "326e1540-b870-44ef-ba71-cf71e7364057", "type": "concept", "title": "Triage, scarce resources, ventilators, vaccines, medications, and staffing"}, {"id": "799d8ed0-1720-4e68-bbe5-6816e2994626", "type": "concept", "title": "Fair process and anti-discrimination safeguards"}, {"id": "6b153040-071e-4abd-b513-916f20050d3c", "type": "concept", "title": "Appeals and transparency"}]}, {"id": "ecaab591-7edd-4d87-b151-9a22ad37c3d4", "type": "subtopic", "title": "Preparedness and resilience", "description": "Learners connect law and ethics to planning before crisis.", "children": [{"id": "c7e9755b-7185-4734-9d88-ab7cc8f7348d", "type": "concept", "title": "Exercises, continuity planning, risk communication, and community partnerships"}, {"id": "d2de303e-34e2-4250-8b20-244bebdc5006", "type": "concept", "title": "Vulnerable populations"}, {"id": "5a2e6459-b7ff-4eba-9469-fe4f6caddcee", "type": "concept", "title": "After-action review and reform"}]}]}, {"id": "b8f23815-287f-445c-975e-7e29d80d0c84", "type": "topic", "title": "Legal Epidemiology, Policy Surveillance, and Law as a Public Health Intervention", "description": "Use law as measurable public health data and as an intervention that can be evaluated.", "children": [{"id": "71557f7e-80a3-44c9-9edd-3ca2a9a5789f", "type": "subtopic", "title": "Legal epidemiology", "description": "Students learn to study law as a factor that shapes health outcomes.", "children": [{"id": "ee8f17cb-2951-4281-9313-4e9fb0d52f41", "type": "concept", "title": "Scientific study of law and legal practices"}, {"id": "97e34810-2a61-4a82-b9bf-a5bf2822cade", "type": "concept", "title": "Policy surveillance"}, {"id": "6d37725f-0713-41c4-8655-12d158ad0dfa", "type": "concept", "title": "Natural experiments and comparative law"}]}, {"id": "f65fa60a-e10e-4717-8eb4-6e687b576386", "type": "subtopic", "title": "Policy evaluation", "description": "The gist is to test whether laws work as intended.", "children": [{"id": "42c58f91-6774-4486-9881-f5de4e41922e", "type": "concept", "title": "Implementation, enforcement,